def rankTeams(votes):
    if not votes:
        return ""

    n = len(votes[0])
    count = {}

    # Initialize count for each team present in the first vote
    for char in votes[0]:
        count[char] = [0] * n

    # Count the ranks
    for vote in votes:
        for i, char in enumerate(vote):
            count[char][i] += 1

    # Sort the teams based on the rules
    # Key: (-count at position 0, -count at position 1, ..., team letter)
    # We use negative counts because we want descending order for counts
    # and ascending order for the team letter (alphabetical)
    teams = list(count.keys())
    teams.sort(key=lambda x: ([-count[x][i] for i in range(n)] + [x]))

    return "".join(teams)
